import {recordId} from './ids.js';
import {escapeHTML as esc} from './learning.js';
import {assignPageNumbers,journalPageCount,journalSpread,MAX_NOTEBOOK_PAGES} from './notebook-data.js';
export function createNotebook(api){
 const root=document.querySelector('#notebook-page'),phone=matchMedia('(max-width:850px)'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let page=1,tab='notes',timer=null,dirty=false,turning=false,lastNewest=null,confirmDelete=0;
 try{page=Math.max(1,Math.min(100,Number(sessionStorage.getItem('vnscape-journal-page'))||1))}catch{}
 const state=()=>api.getState();const noteAt=n=>state().notes.find(x=>x.pageNumber===n);
 function status(text){const el=root.querySelector('#book-save-status');if(el)el.textContent=text}
 function flush(){if(timer)clearTimeout(timer);timer=null;if(!dirty)return;if(state().notes.some(n=>n.body.trim()))api.trackActivity?.();const saved=api.persist();dirty=false;status(saved===false?'Chưa lưu được trên thiết bị. Hãy xuất bản sao.':'Đã lưu trên thiết bị')}
 function queueSave(){dirty=true;status('Đang lưu…');if(timer)clearTimeout(timer);timer=setTimeout(flush,450)}
 function frontispiece(){return `<div class="book-frontispiece"><img src="assets/brand-mark.svg" alt="" width="53" height="53"><span class="paper-eyebrow">VNSCAPE / FIELD JOURNAL</span><h2>Những điều<br>mình tìm thấy.</h2><p>Thuộc về <strong>${esc(state().name)}</strong></p><svg class="journal-botanical" viewBox="0 0 240 220" fill="none" aria-hidden="true"><path d="M120 210C106 158 128 75 156 12M121 153C59 161 27 121 25 78c64-1 97 27 96 75Zm8-52c-4-56 34-84 86-83-3 54-30 87-86 83Z" stroke="currentColor" stroke-width="1.5"/><path d="m28 83 91 67m17-53 72-72M51 92l1 33m29-13v27m73-59 2-35m23 18 1-31" stroke="currentColor" stroke-width=".8"/></svg><p class="frontispiece-quote">Một câu hỏi hay<br>là khởi đầu của một chuyến đi.</p><span class="paper-imprint">QUAN SÁT · TÒ MÒ · KHÁM PHÁ</span></div>`}
 function paper(n){if(n===0)return `<section class="journal-paper inside-cover" aria-label="Trang mở đầu">${frontispiece()}</section>`;if(n>MAX_NOTEBOOK_PAGES)return `<section class="journal-paper journal-end"><p>Hẹn một khám phá mới.</p></section>`;const note=noteAt(n);return `<section class="journal-paper" data-paper="${n}" aria-label="Trang ghi chép ${n}"><div class="paper-topline"><span>GHI CHÉP KHÁM PHÁ</span><span>${note?api.formatDate(note.date):'Một trang đang chờ bạn'}</span></div><input class="journal-title" data-journal-field="title" data-page-number="${n}" aria-label="Tiêu đề trang ${n}" placeholder="Đặt tên cho một phát hiện…" maxlength="100" value="${esc(note?.title||'')}"><textarea class="journal-writing" data-journal-field="body" data-page-number="${n}" aria-label="Nội dung trang ${n}" placeholder="Hôm nay mình quan sát thấy…\n\nMình nghĩ rằng…\n\nCâu hỏi muốn tìm hiểu tiếp…" maxlength="6000" spellcheck="false">${esc(note?.body||'')}</textarea><div class="paper-bottomline"><span>VNSCAPE · SỔ TAY THỰC ĐỊA</span><span class="paper-page-number">${String(n).padStart(2,'0')}</span></div></section>`}
 function paint(){if(tab!=='notes'||!root.querySelector('.book-pages'))return;page=Math.max(1,Math.min(page,journalPageCount(state().notes)));const visible=journalSpread(page,phone.matches);root.querySelector('.book-pages').innerHTML=visible.map(paper).join('');const count=journalPageCount(state().notes);root.querySelector('#book-page-status').textContent=`Trang ${visible.filter(x=>x>0&&x<=100).join('–')} / ${count}`;root.querySelector('#book-page-select').innerHTML=Array.from({length:count},(_,i)=>`<option value="${i+1}" ${i+1===page?'selected':''}>Trang ${i+1}${noteAt(i+1)?' · '+esc(noteAt(i+1).title||'Chưa đặt tên'):''}</option>`).join('');const previous=root.querySelector('[data-book-action="previous"]'),next=root.querySelector('[data-book-action="next"]');previous.disabled=page<=1;next.disabled=phone.matches?page>=count:visible[visible.length-1]>=count;const deleteButton=root.querySelector('[data-book-action="delete"]');deleteButton.disabled=!noteAt(page);deleteButton.textContent='Xóa trang đang chọn';root.querySelector('#journal-note-count').textContent=state().notes.length;renderIndex();try{sessionStorage.setItem('vnscape-journal-page',String(page))}catch{}}
 function renderIndex(){const el=root.querySelector('.journal-index-list');if(!el)return;el.innerHTML=state().notes.length?[...state().notes].sort((a,b)=>a.pageNumber-b.pageNumber).map(n=>`<button class="${n.pageNumber===page?'selected':''}" data-book-page="${n.pageNumber}"><span>${String(n.pageNumber).padStart(2,'0')}</span><span>${esc(n.title||'Trang chưa đặt tên')}</span></button>`).join(''):'<p>Gõ trực tiếp lên giấy.<br>Mỗi phát hiện sẽ xuất hiện trong mục lục này.</p>'}
 function snapshot(el){const clone=el.cloneNode(true);clone.querySelectorAll('input,textarea').forEach((field,i)=>{const original=el.querySelectorAll('input,textarea')[i],text=document.createElement('div');text.className=field.className;text.textContent=original.value||original.placeholder;field.replaceWith(text)});return clone}
 function go(next,animate=true){if(turning)return;flush();const count=journalPageCount(state().notes);next=Math.max(1,Math.min(count,next));const oldVisible=journalSpread(page,phone.matches),newVisible=journalSpread(next,phone.matches);if(oldVisible.join()===newVisible.join()){page=next;paint();return}const forward=next>page,stage=root.querySelector('.book-pages');const old=stage?.querySelector(forward?'.journal-paper:last-child':'.journal-paper:first-child');const face=old?snapshot(old):null;page=next;confirmDelete=0;paint();if(!animate||reduced.matches||!face)return;turning=true;const sheet=document.createElement('div');sheet.className=`page-turn-sheet ${forward?'turn-forward':'turn-backward'}`;const front=document.createElement('div');front.className='turn-face turn-front';front.append(face);const back=document.createElement('div');back.className='turn-face turn-reverse';back.innerHTML='<div class="turn-paper-texture"></div>';sheet.append(front,back);stage.append(sheet);root.querySelector('.field-journal').classList.add('is-turning');const done=()=>{sheet.remove();turning=false;root.querySelector('.field-journal')?.classList.remove('is-turning')};sheet.addEventListener('animationend',done,{once:true});setTimeout(done,750)}
 function render(nextTab='notes'){flush();tab=nextTab;const unpagedNewest=state().notes[0]&&!Number.isInteger(state().notes[0].pageNumber);assignPageNumbers(state().notes);const newest=state().notes[0];if((unpagedNewest||lastNewest!==null)&&newest&&newest.id!==lastNewest)page=newest.pageNumber;lastNewest=newest?.id||'';const common=`<div class="journal-tabs"><button data-action="notes-tab" class="${tab==='notes'?'selected':''}" aria-pressed="${tab==='notes'}">${api.icon('notebook')} Quyển sổ <span id="journal-note-count">${state().notes.length}</span></button><button data-action="saved-tab" class="${tab==='saved'?'selected':''}" aria-pressed="${tab==='saved'}">${api.icon('bookmark')} Bài đã lưu <span>${state().saved.length}</span></button></div>`;
  if(tab==='saved'){root.innerHTML=common+`<div class="journal-saved-list">${state().saved.length?state().saved.map(id=>api.resultHTML(api.lessons.find(l=>l.id===id))).join(''):'<div class="empty-state"><h2>Giữ lại một bài học hay.</h2><p>Đánh dấu bài học để tìm lại tại đây.</p><a class="text-button" href="#/explore">Đi tìm một khám phá →</a></div>'}</div>`;return}
  root.innerHTML=common+`<div class="journal-toolbar"><div><span class="journal-ready-dot"></span><span id="book-save-status" role="status">Tự động lưu khi bạn viết</span></div><div class="journal-tools"><button data-book-action="cover">Xem bìa</button><button data-book-action="add">${api.icon('plus')} Thêm trang</button><button data-book-action="save">${api.icon('check')} Lưu ngay</button><button data-action="export-notes">${api.icon('download')} Xuất sổ tay</button></div></div><div class="journal-desk"><aside class="journal-index"><span class="eyebrow">MỤC LỤC CỦA BẠN</span><h2>Điều đã tìm thấy</h2><div class="journal-index-list"></div><p class="journal-index-tip">Bạn có thể gõ trên trang giấy, chọn mục lục hoặc dùng nút lật trang.</p></aside><div class="book-column"><div class="field-journal" aria-label="Quyển sổ tay có thể viết và lật trang"><div class="book-pages"></div><div class="journal-spine" aria-hidden="true"></div><button class="journal-front-cover" data-book-action="open" aria-label="Mở quyển sổ"><img src="assets/brand-mark.svg" alt=""><span>VNSCAPE</span><strong>Sổ tay<br>khám phá</strong><span>FIELD NOTES · ${new Date().getFullYear()}</span><small>Chạm để mở sổ →</small></button></div><div class="book-navigation"><button data-book-action="previous" aria-label="Lật về trang trước">${api.icon('arrow-right')}<span>Trang trước</span></button><label for="book-page-select" class="sr-only">Chọn trang trong sổ</label><select id="book-page-select" aria-label="Chọn trang trong sổ"></select><button data-book-action="next" aria-label="Lật sang trang sau"><span>Trang sau</span>${api.icon('arrow-right')}</button></div><div class="book-footline"><span id="book-page-status" aria-live="polite"></span><button data-book-action="delete">Xóa trang đang chọn</button></div></div></div><p class="journal-privacy">Nội dung được lưu trong trình duyệt này. Xuất sổ tay để giữ bản sao khi đổi thiết bị.</p>`;paint();
 }
 document.addEventListener('input',e=>{const field=e.target.closest('[data-journal-field]');if(!field||!root.contains(field))return;const number=Number(field.dataset.pageNumber);let note=noteAt(number);if(!note){if(state().notes.length>=MAX_NOTEBOOK_PAGES){status('Sổ đã đủ 100 trang. Hãy chỉnh sửa một trang đang có.');return}note={id:recordId(),title:'',body:'',date:new Date().toISOString(),pageNumber:number};state().notes.unshift(note);lastNewest=note.id}note[field.dataset.journalField]=field.value;note.date=new Date().toISOString();page=number;confirmDelete=0;const deleteButton=root.querySelector('[data-book-action=delete]');if(deleteButton){deleteButton.textContent='Xóa trang đang chọn';deleteButton.disabled=false}const count=root.querySelector('#journal-note-count');if(count)count.textContent=state().notes.length;renderIndex();queueSave()});
 document.addEventListener('change',e=>{if(e.target.id==='book-page-select')go(Number(e.target.value))});
 document.addEventListener('click',e=>{const index=e.target.closest('[data-book-page]');if(index){go(Number(index.dataset.bookPage));return}const b=e.target.closest('[data-book-action]');if(!b||!root.contains(b))return;const action=b.dataset.bookAction;if(action==='save'){dirty=true;flush()}if(action==='previous')go(phone.matches?page-1:Math.max(1,Math.floor(page/2)*2-2));if(action==='next')go(phone.matches?page+1:Math.floor(page/2)*2+2);if(action==='add'){flush();const target=Math.min(100,Math.max(0,...state().notes.map(n=>n.pageNumber))+1);go(target);setTimeout(()=>root.querySelector(`[data-paper="${target}"] textarea`)?.focus({preventScroll:true}),reduced.matches?0:600)}if(action==='cover'){flush();root.querySelector('.field-journal').classList.add('is-closed')}if(action==='open')root.querySelector('.field-journal').classList.remove('is-closed');if(action==='delete'){const note=noteAt(page);if(!note)return;if(confirmDelete!==page){confirmDelete=page;b.textContent='Xác nhận xóa nội dung trang này';return}flush();state().notes=state().notes.filter(n=>n.id!==note.id);api.persist();render();api.toast('Đã xóa nội dung trang được chọn.')}});
 window.addEventListener('beforeunload',flush);phone.addEventListener('change',()=>{if(document.body.dataset.page==='notebook')render(tab)});
 root.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();flush();return}if(e.target.matches('textarea,input,select'))return;if(e.key==='ArrowRight'){e.preventDefault();go(phone.matches?page+1:Math.floor(page/2)*2+2)}if(e.key==='ArrowLeft'){e.preventDefault();go(phone.matches?page-1:Math.max(1,Math.floor(page/2)*2-2))}});
 return {render,flush,go};
}
